void bubbleSort(int* arr, int size, bool (*compare)(int, int)) {
    for (int i = 0; i < size; ++i)
        for (int j = 0; j + 1 < size - i; ++j)
            if (compare(arr[j + 1], arr[j])) { int t = arr[j]; arr[j] = arr[j + 1]; arr[j + 1] = t; }
}

