    int x1 = std::max(a.x, b.x), x2 = std::min(a.x + a.width, b.x + b.width);
    int y1 = std::max(a.y, b.y), y2 = std::min(a.y + a.height, b.y + b.height);
    if (x1 < x2 && y1 < y2) return {x1, y1, x2 - x1, y2 - y1};
    return {0, 0, 0, 0};
}

