class Vector3D {
public:
    Vector3D() : c_{0, 0, 0} {}
    Vector3D(double x, double y, double z) : c_{x, y, z} {}
    double length() const { return std::sqrt(c_[0] * c_[0] + c_[1] * c_[1] + c_[2] * c_[2]); }
